import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { renderHistorianSystemPrompt } from "../src/hooks/magic-context/historian-prompt-render";

const root = resolve(import.meta.dir, "../src/hooks/magic-context/two-pass-prompts");
const sources = {
    TWO_PASS_SYSTEM: "system.md",
    TWO_PASS_TURN_ONE: "turn-one.md",
    TWO_PASS_TURN_TWO: "turn-two.md",
};
const output = [
    "// Generated by scripts/build-two-pass-prompts.ts. Edit the adjacent Markdown sources.",
    ...Object.entries(sources).map(([name, file]) => {
        const source = readFileSync(resolve(root, file), "utf8");
        const text =
            name === "TWO_PASS_SYSTEM" ? renderHistorianSystemPrompt(source, "combined") : source;
        return `export const ${name} = ${JSON.stringify(text)};`;
    }),
    "",
].join("\n");
const target = resolve(root, "prompts.generated.ts");
// Use the installed project formatter so generation and the package lint gate agree.
const formatted = execFileSync(
    process.execPath,
    [
        "run",
        "--cwd",
        resolve(import.meta.dir, ".."),
        "biome",
        "format",
        "--stdin-file-path",
        target,
    ],
    { input: output, encoding: "utf8" },
);
const rustTarget = resolve(
    import.meta.dir,
    "../../../crates/mc-module/testdata/historian-two-pass-system-prompt.txt",
);
const system = renderHistorianSystemPrompt(
    readFileSync(resolve(root, "system.md"), "utf8"),
    "combined",
);
if (process.argv.includes("--check")) {
    if (readFileSync(target, "utf8") !== formatted) throw new Error("two_pass_prompts_stale");
    if (readFileSync(rustTarget, "utf8") !== system) throw new Error("two_pass_rust_prompt_stale");
    console.log(`two-pass prompts: ${Object.keys(sources).length} sources checked`);
} else {
    writeFileSync(target, formatted);
    writeFileSync(rustTarget, system);
    console.log(`two-pass prompts: ${Object.keys(sources).length} sources generated`);
}
